create table public.group_profiles (id uuid primary key default gen_random_uuid(), name text not null, config jsonb not null, version int not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.individual_profiles (id uuid primary key default gen_random_uuid(), name text not null, config jsonb not null, version int not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.scenarios (id uuid primary key default gen_random_uuid(), name text not null, group_profile_id uuid references public.group_profiles(id) on delete set null, individual_profile_id uuid references public.individual_profiles(id) on delete set null, config jsonb not null, created_at timestamptz not null default now());
create table public.simulation_runs (id uuid primary key default gen_random_uuid(), scenario_id uuid references public.scenarios(id) on delete set null, status text not null default 'COMPLETED', engine text not null, model_version text not null, seed bigint not null, input_hash text not null, input jsonb not null, summary jsonb, frames jsonb, agents jsonb, error text, created_at timestamptz not null default now());
create table public.source_documents (id text primary key, title text not null, author text, category text, url text, evidence_tier text, verification text, license text, summary text, origin text not null default 'bibliography', created_at timestamptz not null default now());
create table public.source_excerpts (id uuid primary key default gen_random_uuid(), source_id text not null references public.source_documents(id) on delete cascade, page text, excerpt text not null, claim_status text not null default 'unverified', independence_cluster text, provenance jsonb not null default '{}', created_at timestamptz not null default now());
create table public.chat_sessions (id uuid primary key default gen_random_uuid(), scope text not null, title text not null default 'New conversation', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.chat_messages (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.chat_sessions(id) on delete cascade, role text not null, content text not null, citations jsonb not null default '[]', model text, created_at timestamptz not null default now());
create table public.neural_runs (id uuid primary key default gen_random_uuid(), mode text not null, seed bigint not null, input jsonb not null, summary jsonb not null, created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['group_profiles','individual_profiles','scenarios','simulation_runs','source_documents','source_excerpts','chat_sessions','chat_messages','neural_runs'] loop
 execute format('grant all on public.%I to service_role', t);
 execute format('alter table public.%I enable row level security', t);
end loop; end $$;